-- Conferencia: apos as 3 fatias, jogos deve ser 75
SELECT 'jogos no Controle: ' || count(*) AS resultado
FROM competition_events
WHERE competition_id = (SELECT id FROM competitions WHERE slug = 'paulistao-a1');